#[instrument(skip(payload))]
pub fn sanitize_chat_input(payload: &[u8]) -> Result<String, SanitizerError> {
    let mut log = OpenOptions::new()
        .create(true)
        .append(true)
        .open(LOG_PATH)
        .expect("failed to open trm_paste.log");

    let ts = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_millis();

    if payload.len() > MAX_PAYLOAD_BYTES {
        writeln!(
            log,
            "{} WARN size_exceeded bytes={} limit={}",
            ts, payload.len(), MAX_PAYLOAD_BYTES
        ).ok();
        warn!(bytes = payload.len(), "truncating oversized paste");
        return Ok(String::from_utf8_lossy(&payload[..MAX_PAYLOAD_BYTES]).into_owned());
    }

    // Binary detection via non-UTF-8 or control characters
    if payload.iter().any(|&b| b == 0 || (b < 0x20 && b != b'\n' && b != b'\r' && b != b'\t')) {
        writeln!(log, "{} WARN binary_detected bytes={}", ts, payload.len()).ok();
        warn!("binary data detected – applying UTF-8 lossy fallback");
        return Ok(String::from_utf8_lossy(payload).into_owned());
    }

    match std::str::from_utf8(payload) {
        Ok(s) => {
            info!(bytes = payload.len(), "clean text paste accepted");
            Ok(s.to_owned())
        }
        Err(_) => {
            writeln!(log, "{} WARN utf8_fallback bytes={}", ts, payload.len()).ok();
            Ok(String::from_utf8_lossy(payload).into_owned())
        }
    }
}
